mapper.select:
SELECT r.reply_id AS reply_id, r.comment_id AS comment_id, r.parent_reply_id AS parent_reply_id, r.user_id AS user_id, u.nickname AS nickname, u.img_url AS avatar_url, u2.nickname AS reply_to_nickname, r.reply_text AS reply_text, r.like_count AS like_count, r.dislike_count AS dislike_count, r.gmt_create AS gmt_create FROM comment_replies r LEFT JOIN users u ON r.user_id = u.user_id LEFT JOIN comment_replies r2 ON r.parent_reply_id = r2.reply_id LEFT JOIN users u2 ON r2.user_id = u2.user_id WHERE r.enable = 1 AND r.comment_id IN
#{cid}
ORDER BY r.gmt_create ASC, r.reply_id ASC
